#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;
};

int main() {
    Cat c1;
    Cat c2;
    c1.name = "小橘";
    c1.fish = 3;
    c2.name = "狸花";
    c2.fish = 1;
    c1.fish = c1.fish + 4;
    cout << c1.name << " 的账上是 " << c1.fish << " 条" << endl;
    cout << c2.name << " 的账上是 " << c2.fish << " 条" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    void meow() {
        cout << name << " 说：本喵有 " << fish << " 条" << endl;
    }
};

int main() {
    Cat c1;
    c1.name = "大胖";
    c1.fish = 5;
    c1.meow();
    c1.fish = 2;
    c1.meow();
    return 0;
}
